<script lang="ts">
  import type { DirectionViewProps, Precision } from '../../contract';
  import MapSurface from '../../components/MapSurface.svelte';
  import RecordList from '../../components/RecordList.svelte';
  let { state, records, dispatch }: DirectionViewProps = $props();
  const categories=['Poultry','Pig','Dairy','Processing','Laboratory','Aquaculture'];
  const precisions:readonly Precision[]=['exact','city','coarse','unmapped'];
  const selected=$derived(records.find(record=>record.id===state.selectedId)??null);
  const aggregateRecords=$derived(state.aggregateMemberIds===null?records:records.filter(record=>state.aggregateMemberIds!.includes(record.id)));
  const mapped=$derived(records.filter(record=>record.latitude!==null&&record.longitude!==null));
  const resultCount=$derived(aggregateRecords.length); const active=$derived(state.filters.categories.length+state.filters.precisions.length); const v1Logo=`${import.meta.env.BASE_URL}assets/icon.png`;
  function category(value:string,checked:boolean){dispatch({type:'filters',value:{...state.filters,categories:checked?[...state.filters.categories,value]:state.filters.categories.filter(item=>item!==value)}})}
  function precision(value:Precision,checked:boolean){dispatch({type:'filters',value:{...state.filters,precisions:checked?[...state.filters.precisions,value]:state.filters.precisions.filter(item=>item!==value)}})}
</script>
<section class="field-view">
 <header class="spine"><a class="brand" href="#/map?f1a=field" aria-label="Until Every Cage map home"><img src={v1Logo} alt=""/><span>Until Every Cage</span></a><form class="search" role="search" onsubmit={event=>event.preventDefault()}><label for="field-search">Search records</label><input id="field-search" type="search" placeholder="Search records" value={state.query} oninput={event=>dispatch({type:'query',value:event.currentTarget.value})}/></form><details class="filters"><summary>Filters {#if active}<b>{active}</b>{/if}</summary><div class="filter-sheet"><strong>Refine results</strong><p class="category-key"><i class="poultry"></i>Poultry <i class="pig"></i>Pig <i class="dairy"></i>Dairy <i class="processing"></i>Processing <i class="laboratory"></i>Lab <i class="aquaculture"></i>Aquaculture</p><fieldset><legend>Category</legend>{#each categories as value}<label><input type="checkbox" checked={state.filters.categories.includes(value)} onchange={event=>category(value,event.currentTarget.checked)}/>{value}</label>{/each}</fieldset><fieldset><legend>Location precision</legend>{#each precisions as value}<label><input type="checkbox" checked={state.filters.precisions.includes(value)} onchange={event=>precision(value,event.currentTarget.checked)}/>{value}</label>{/each}</fieldset><button type="button" onclick={()=>dispatch({type:'reset-filters'})}>Clear filters</button></div></details></header>
 <section class="map-stage" aria-label="Investigative map field">
  {#if state.scenario==='loading'}<div class="status" role="status">Loading records…</div>{:else if state.scenario==='error'}<div class="status" role="alert">Records unavailable. No live fallback was attempted.</div>{:else}<MapSurface records={mapped} {state} onselect={id=>dispatch({type:'select',value:id})} onaggregate={ids=>dispatch({type:'aggregate',value:ids})} onbasemap={value=>dispatch({type:'basemap',value})} onviewport={value=>dispatch({type:'viewport',value})}/>{/if}
  {#if state.scenario==='empty'||(state.scenario!=='loading'&&state.scenario!=='error'&&records.length===0)}<div class="status" role="status">No records match this search and these filters.</div>{/if}
  <button class="results-toggle" type="button" aria-expanded={state.listOpen} aria-controls="field-record-list" onclick={()=>dispatch({type:'list',value:!state.listOpen})}>Results <b>{resultCount}</b></button>
  {#if state.listOpen&&!selected}<aside class="results" id="field-record-list" aria-label="Synchronized results"><header><strong>Results <span>{resultCount}</span></strong><button type="button" aria-label="Close results" onclick={()=>dispatch({type:'list',value:false})}>×</button></header><RecordList records={aggregateRecords} selectedId={state.selectedId} onselect={id=>dispatch({type:'select',value:id})}/></aside>{/if}
  {#if selected}<aside class="reading-sheet" aria-labelledby="record-title"><button type="button" class="close" aria-label="Close record detail" onclick={()=>dispatch({type:'select',value:null})}>×</button><small>{selected.category} · {selected.id}</small><h2 id="record-title">{selected.name}</h2><p>{selected.locality}, {selected.country}</p><dl><div><dt>Location</dt><dd>{selected.precision} precision</dd></div><div><dt>Release</dt><dd>Review sample</dd></div><div><dt>Source</dt><dd>Development fixture</dd></div></dl></aside>{/if}
 </section>
</section>
